//! `hs_door` / `hs_door_l01` / `hs_door_l03` (15 builds, one level each: EP1 L03B, EP2 L01A/B/C
//! L02A/B L03A, EP3 L01, EP4 L01/L02A/B, EP6 L01/L02/L04A/B): door hot spots linking the same hs_door_base.c as
//! [`super::hs_door_l01`] (ported there). The builds differ in the base only by data layout, door
//! count, radar/camera ids, lock/open sounds and debug traces ([`Var`], generated by
//! `tools/rustport/gen_hs_door.py` with the goCustomDataDoor images into `builds.rs`), plus a local
//! .c per build (ported below, dispatched on the build).
//! Port of `Game Logic Modules/*/Objects/HOTSPOTS/*/hs_door{,_l01,_l03}__<sha8>/hs_door{,_L01,_L03}.c`.
#![allow(non_snake_case, non_upper_case_globals, unused_variables)]

mod builds;
pub use builds::VARS;

use super::hs_door_l01 as base;
use super::hs_door_l01::{lr, lw, GB};
use crate::engine::*;
use crate::logic::{LResult, ModuleDef};

/// per-build parameters of hs_door_base.c (module-relative addresses)
pub struct Var {
    pub name: &'static str,
    /// number of goCustomDataDoor entries scanned by ST_FIRSTMOVE
    pub n: u32,
    pub radar: u32,
    /// camera object receiving msg 0x54
    pub cam: u32,
    pub snd_lock: u32,
    pub snd_open: u32,
    /// PrintDebugInfo traces present
    pub dbg: bool,
    /// pGame (pGameObj..pMiscFunc follow at +4)
    pub pgame: u32,
    pub cam27: u32,
    /// pExtra (pLocalDataHSDoor, pGlobalDataHSDoor follow at +4)
    pub pextra: u32,
    pub pfunction: u32,
    pub plight: u32,
    pub size: u32,
}

pub static MODULE: ModuleDef = ModuleDef {
    name: "hs_door",
    // the largest build image (64b2633a)
    data_size: 0xf110,
    ctor: hs_doorConstructor,
    dtor: hs_doorDestructor,
    register: None,
    init: &[],
    build_init: Some(build_init),
};

pub fn build_index(key: &str) -> Option<usize> {
    builds::KEYS.iter().position(|&k| k == key)
}

fn build_init(m: &mut Mem, data: Ptr, b: usize) {
    // words, then the string pointers (R_MIPS_32 into .text) as interned strings, in relocation order
    let img = crate::engine::gamedata::c2rs_image(builds::KEYS[b], builds::RUNS[b]);
    let s: Vec<(u32, String)> = img.rels.iter().map(|&(a, t)| (a, crate::engine::gamedata::text_cstr(builds::KEYS[b], t))).collect();
    let s: Vec<(u32, &str)> = s.iter().map(|(a, x)| (*a, x.as_str())).collect();
    base::build_init_tab(m, data, &img.words, &s);
}

fn key(e: &Engine) -> &'static str {
    builds::KEYS[e.rt.cur_build()]
}
fn id(e: &mut Engine) -> u32 {
    APIgameobj::GetID(e, SELF, NULL)
}
fn leader(e: &Engine) -> u32 {
    e.r32(GB(e, 0) + 8)
}
fn or(e: &mut Engine, a: Ptr, v: u32) {
    let x = e.r32(a) | v;
    e.w32(a, x);
}
fn and(e: &mut Engine, a: Ptr, v: u32) {
    let x = e.r32(a) & v;
    e.w32(a, x);
}
fn pfun(e: &Engine) -> Ptr {
    e.rt.cur_data() + (VARS[e.rt.cur_build()].pfunction - 0x10000)
}
fn plight(e: &Engine) -> Ptr {
    e.rt.cur_data() + (VARS[e.rt.cur_build()].plight - 0x10000)
}
/// `if (!IsTextDisplayed()) { InitStruct(s); s[0] = 0x40000000; ShowText(t, s); }`
fn show_text(e: &mut Engine, t: u32) {
    let s = e.alloca(0x40);
    LIBApiText::InitStruct(e, s);
    e.w32(s, 0x4000_0000);
    LIBApiText::ShowText(e, t, s);
}
/// SendMessageTo(to, 0x1de, p, &[w])
fn msg1de(e: &mut Engine, to: u32, p: u32, w: u32) {
    let s = e.alloca(0x10);
    e.w32(s, w);
    APIgameobj::SendMessageTo(e, to, NULL, 0x1de, p, s);
}

/// ext fn 4
pub fn fcback_COLLISION_LOCAL(e: &mut Engine, p: u32) -> LResult<u64> {
    match key(e) {
        "64b2633a" => {
            let _ = id(e);
            if IsCafeteriaHotSpot(e) != 0 && IsGuardInRoom(e) != 0 {
                return Ok(0);
            }
        }
        "876ca9b6" => {
            let i = id(e);
            if lr(e, 0x804) == 0 && (0x2a00_000d..=0x2a00_0010).contains(&i) {
                let l = leader(e);
                APIgameobj::SendMessageTo(e, l, NULL, 0x1d1, 0, NULL);
            }
        }
        "9e2d68e4" => {
            if lr(e, 0x804) == 0 {
                let gb0 = GB(e, 0);
                match id(e) {
                    0x2a00_000a => {
                        let t = lr(e, 0x864);
                        APIextra::TimerUnregisterNotify(e, SELF, t);
                    }
                    0x2a00_0009 => {
                        if e.r32(gb0 + 0x14) & 0x0800_090d != 0 {
                            return Ok(0);
                        }
                        if e.r32(GB(e, 2) + 0xc) & 0x800 != 0 {
                            APIgameobj::SendMessageTo(e, 0x2a10_0006, NULL, 0x2a, 3, NULL);
                        }
                    }
                    0x2a00_000b => {
                        if e.r32(gb0 + 0x14) & 0x0e20_090d != 0 || e.r32(GB(e, 2) + 0x10) & 0x400 != 0 {
                            return Ok(0);
                        }
                        let f = e.alloca(0x20); // auStack_50
                        for (o, v) in [(0x10, 0), (4, 0x3f00_0000), (0xc, 0x3e4c_cccd), (8, 0x3e4c_cccd), (0, 1)] {
                            e.w32(f + o, v);
                        }
                        LIBApiCFunctions::DoFade(e, f);
                        let t = lr(e, 0x860);
                        APIextra::TimerReset(e, t);
                        APIextra::TimerSetFrequency(e, t, 0.55);
                        APIextra::TimerRegisterNotify(e, SELF, t, 5);
                        return Ok(1);
                    }
                    0x2a00_000c => {
                        if e.r32(gb0 + 0x14) & 0x0800_090d != 0 {
                            return Ok(0);
                        }
                        let f34 = e.r32(gb0 + 0x34);
                        if (!f34) & 0x110 == 0 && f34 & 0x1400 == 0 {
                            let l = leader(e);
                            APIgameobj::SendMessageTo(e, l, NULL, 0x86, 1, NULL);
                            return Ok(0);
                        }
                        if e.r32(GB(e, 2) + 0x10) & 0x400 == 0 {
                            return Ok(0);
                        }
                        msg1de(e, 0x2a00_000e, 2, 0x8000_000a);
                        APIgameobj::SendMessageTo(e, 0x2a00_0110, NULL, 0xde, 0, NULL);
                        APIgameobj::SetGroupID(e, SELF, 6);
                        let t = lr(e, 0x864);
                        APIextra::TimerReset(e, t);
                        APIextra::TimerSetFrequency(e, t, 8.0);
                        APIextra::TimerRegisterNotify(e, SELF, t, 5);
                        return Ok(1);
                    }
                    _ => {}
                }
            }
        }
        "9e67afa5" => match id(e) {
            0x2a00_000c => {
                lw(e, 0x80c, 1);
                // moCameraParams_43 (local static at 0x11880, ELF symtab); DAT_118bc.. = P[0xf..0x11]
                let cp = e.rt.cur_data() + (0x11880 - 0x10000);
                for (o, v) in [(0, 0x62), (0x3c, 0), (0x40, 1), (0x44, 0)] {
                    e.w32(cp + o, v);
                }
                APIgameobj::SendMessageTo(e, 0x2a00_000f, NULL, 0x54, 0, cp);
                APIgameobj::SendMessageTo(e, 0x2a10_0006, NULL, 0x1e, 0, NULL);
                return Ok(1);
            }
            0x2a00_000d => {
                let a = GB(e, 2) + 0x1c;
                if e.r32(a) & 2 == 0 {
                    or(e, a, 2);
                    msg1de(e, 0x2a00_000f, 0, 0x8000_0003);
                    APIgameobj::SetGroupID(e, SELF, 6);
                }
                return Ok(1);
            }
            _ => {}
        },
        "9efa6340" => match id(e) {
            0x2a00_0023 => {
                let a = GB(e, 2) + 0xc;
                or(e, a, 0x0200_0000);
                return Ok(1);
            }
            0x2a00_0025 => {
                if LIBApiText::IsTextDisplayed(e) == 0
                    && APIgameobj::SendMessageTo(e, 0x2a00_0046, NULL, 0x1da, 0, NULL) == 0
                {
                    show_text(e, 0x159);
                }
                return Ok(0);
            }
            _ => {}
        },
        "9f60c594" => {
            let _ = id(e);
        }
        "b4cee97a" => {
            if id(e) == 0 {
                return Ok(0);
            }
        }
        "1d6cdf74" => {
            let i = id(e);
            if i == 0x2a00_00f7 && e.r32(GB(e, 0) + 0x34) & 1 != 0 {
                if LIBApiText::IsTextDisplayed(e) == 0 {
                    show_text(e, 0x157);
                }
                return Ok(0);
            }
            if lr(e, 0x804) == 0 {
                match i {
                    0x2a00_00f7 | 0x2a00_00f8 => {
                        APIgameobj::SendMessageTo(e, 0x2a00_0031, NULL, 0xde, 1, NULL);
                    }
                    0x2a00_0100 => {
                        APIgameobj::SendMessageTo(e, 0x2a00_0031, NULL, 0xde, 7, NULL);
                    }
                    0x2a00_00fe => {
                        let a = GB(e, 2) + 0xc;
                        and(e, a, 0xfffd_ffff);
                    }
                    _ => {}
                }
            }
        }
        "32a5bf2e" => {
            let a = GB(e, 0) + 0x44;
            if id(e) == 0x2a00_0005 {
                e.w32(a, 1);
            } else if id(e) == 0x2a00_0004 {
                e.w32(a, 0);
            }
        }
        "68691de5" => {
            let i = id(e);
            if i != 0x2a00_0119 {
                return base::hs_door_baseCB_CollisionDetection(e, p);
            }
            let a = GB(e, 2) + 0x1c;
            if e.r32(p + 8) == leader(e) && e.r32(a) & 2 == 0 {
                APIgameobj::SendMessageTo(e, 0x2a10_0006, NULL, 0x2a, 6, NULL);
                APIgameobj::SendMessageTo(e, 0x2a10_0006, NULL, 0x2a, 7, NULL);
                or(e, a, 2);
                msg1de(e, 0x2a00_0025, 1, 0x8000_0003);
            }
            return Ok(0);
        }
        "f50a6ba2" => {
            let i = id(e);
            if lr(e, 0x804) == 0 && (i == 0x2a00_0125 || i == 0x2a00_0126) {
                let l = leader(e);
                APIgameobj::SendMessageTo(e, l, NULL, 0x1d1, 0, NULL);
            }
        }
        "fd412404" => {
            if id(e) == 0x2a00_0043 {
                APIgameobj::SetGroupID(e, SELF, 6);
                APIgameobj::SendMessageTo(e, 0x2a10_0006, NULL, 0x2a, 5, NULL);
                APIgameobj::SendMessageTo(e, 0x2a10_0006, NULL, 0x2b, 5, NULL);
            }
        }
        // 49cc7562, 852f0c8f, 76d61404: plain forward
        _ => {}
    }
    base::hs_door_baseCB_CollisionDetection(e, p)
}

/// 64b2633a
fn IsCafeteriaHotSpot(e: &mut Engine) -> u32 {
    matches!(id(e), 0x2a00_0027 | 0x2a00_0023 | 0x2a00_003a) as u32
}
/// 64b2633a: one of the two goSecurityGuardInRoomHS guards (0x1f078) within 100 of the door
fn IsGuardInRoom(e: &mut Engine) -> u32 {
    for i in 0..2 {
        let g = e.r32(e.rt.cur_data() + (0x1f078 - 0x10000) + i * 4);
        if LIBApiCFunctions::CheckRangeObject(e, 100.0, g, SELF, 0) != 0 {
            return 1;
        }
    }
    0
}

/// 68691de5 / 76d61404 ext fn 6
pub fn fcback_hs_door_localInputAction_X(e: &mut Engine, _: u32) -> LResult<u64> {
    let i = id(e);
    if key(e) == "68691de5" {
        if i == 0x2a00_0111 {
            APInewSound::Play(e, 0x2a00_0032, 0x8000_0005, 0);
            return Ok(0);
        }
    } else {
        let gb2 = GB(e, 2);
        if i == 0x2a00_0109 && e.r32(gb2 + 0xc) & lr(e, 8) != 0 && e.r32(gb2 + 0x1c) & 8 == 0 {
            APInewSound::Play(e, 0x2a00_002b, 0x8000_0004, 0);
            return Ok(0);
        }
    }
    base::hs_door_baseCB_InputAction_X(e, 0)
}

/// 9e2d68e4 ext fn 5 (replaces the base timer callback)
pub fn fcback_TIMER(e: &mut Engine, p: u32) -> LResult<u64> {
    let vis = |e: &mut Engine, on: [i32; 4]| {
        for (o, v) in [0x1280_0016u32, 0x1280_0017, 0x1280_0018, 0x1280_0019].into_iter().zip(on) {
            APIlight::SetVisible(e, o, v);
        }
    };
    if p == lr(e, 0x860) {
        msg1de(e, 0x2a00_000e, 4, 0x8000_000d);
        APIgameobj::SendMessageTo(e, 0x2a00_000e, NULL, 0xde, 0, NULL);
        APIgameobj::SetGroupID(e, SELF, 6);
        vis(e, [1, 1, 0, 0]);
    } else if p == lr(e, 0x864) {
        vis(e, [0, 0, 1, 1]);
        APIgameobj::SendMessageTo(e, 0x2a10_0006, NULL, 0x2a, 4, NULL);
    }
    Ok(1)
}

pub fn hs_door_localFUNC_MessageHandler(e: &mut Engine, m: u32, p: u32, d: Ptr) -> LResult<u64> {
    match key(e) {
        "9e2d68e4" => match m {
            0xd4 => {
                lw(e, 0x810, 1);
                APIgameobj::SetGroupID(e, SELF, 0);
            }
            0xc1 if lr(e, 0x810) == 0 => {
                APIgameobj::SetGroupID(e, SELF, 0);
                lw(e, 0x810, 0);
                APIgameobj::RegisterNotify(e, SELF, 0xffff_ffff, 3, 4);
            }
            0xdf => {
                let t = lr(e, 0x864);
                APIextra::TimerUnregisterNotify(e, SELF, t);
            }
            _ => {}
        },
        "9e67afa5" => {
            let a = GB(e, 2) + 0x28;
            if m == 0x4f {
                if lr(e, 0x80c) != 0 {
                    let s = e.alloca(0x7e0); // asStack_810
                    let src = e.rt.cur_data() + (0x12690 - 0x10000);
                    e.memcpy(s, src, 0x7dc);
                    or(e, a, 0x10000);
                    let (l, k) = (e.cstr("EP4\\L02B"), e.cstr("EP4L02B"));
                    APIgame::LoadLevel(e, l, k, s);
                }
            } else if m == 0xc1 && lr(e, 0x810) == 0 {
                let a = GB(e, 2) + 0x1c;
                and(e, a, 0xffff_fffd);
            }
        }
        "876ca9b6" => {
            base::hs_door_baseFUNC_MessageHandler(e, m, p, d)?;
            return Ok(0);
        }
        "49cc7562" => {
            if m == 0xdf {
                match id(e) {
                    0x2a00_0115 => {
                        APIgameobj::UnregisterNotify(e, SELF, 0xffff_ffff, 3);
                        return Ok(0);
                    }
                    0x2a00_0117 => {
                        lw(e, 8, 0xffff_ffff);
                        lw(e, 0x10, 0x15a);
                    }
                    _ => {}
                }
            }
        }
        "fd412404" => {
            if m == 0xc1 {
                APIgameobj::SendMessageTo(e, 0x2a10_0006, NULL, 0x2d, 5, NULL);
            }
        }
        "68691de5" => {
            if m == 0xc9 && id(e) == 0x2a00_0119 {
                let a = GB(e, 2) + 0x1c;
                and(e, a, 0xffff_fffd);
            }
        }
        _ => {}
    }
    base::hs_door_baseFUNC_MessageHandler(e, m, p, d)
}

pub fn hs_doorConstructor(e: &mut Engine, api: Ptr, instanceCount: i32) -> LResult<()> {
    base::hs_door_baseConstructor(e, api, instanceCount);
    let k = key(e);
    if instanceCount == 1 {
        APIcons::SetExternalFunction(e, 4, fcback_COLLISION_LOCAL);
        match k {
            "9e2d68e4" => {
                APIcons::SetExternalFunction(e, 5, fcback_TIMER);
            }
            "68691de5" | "76d61404" => {
                APIcons::SetExternalFunction(e, 6, fcback_hs_door_localInputAction_X);
            }
            _ => {}
        }
        if matches!(k, "64b2633a" | "9e2d68e4" | "b4cee97a") {
            let n = e.cstr("ApiCFunctions");
            let v = APIcons::GetApiCustom(e, n);
            let a = pfun(e);
            e.w32(a, v);
        }
        if k == "9e2d68e4" {
            let v = APIcons::GetApiLight(e);
            let a = plight(e);
            e.w32(a, v);
        }
    }
    if k == "9e2d68e4" {
        lw(e, 0x810, 0);
    }
    if matches!(k, "9e2d68e4" | "9e67afa5" | "876ca9b6" | "49cc7562" | "68691de5" | "fd412404") {
        APIcons::SetMessageFunction(e, hs_door_localFUNC_MessageHandler);
    }
    if k == "9e2d68e4" {
        for o in [0x860, 0x864] {
            let t = APIextra::TimerCreate(e);
            lw(e, o, t);
        }
    }
    APIcons::SetInitialState(e, 0);
    Ok(())
}

pub fn hs_doorDestructor(e: &mut Engine, instanceCount: i32) -> LResult<()> {
    if key(e) == "9e2d68e4" {
        for o in [0x860, 0x864] {
            let t = lr(e, o);
            APIextra::TimerDestroy(e, t);
        }
    }
    base::hs_door_baseDestructor(e);
    Ok(())
}
